"""Audit and evaluate the local Dependency prototype feature dataset."""

import argparse
import json
from pathlib import Path

from dependency_expert.features.prototype_evaluation import (
    DEFAULT_SEED,
    DEFAULT_TEST_SIZE,
    evaluate_dataset,
    read_and_audit_dataset,
)

REPOSITORY_ROOT = Path(__file__).resolve().parents[4]
# DEFAULT: use the feature CSV generated by the prototype collector.
DEFAULT_CSV = REPOSITORY_ROOT / "data/datasets/dependency/prototype/dependency_features.csv"
# DEFAULT: keep the evaluation output beside the ignored local dataset artifacts.
DEFAULT_REPORT = REPOSITORY_ROOT / "data/datasets/dependency/prototype/evaluation_report.json"


def main() -> None:
    """Write a reproducible JSON quality audit and held-out evaluation report."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--csv", type=Path, default=DEFAULT_CSV)
    parser.add_argument("--report", type=Path, default=DEFAULT_REPORT)
    parser.add_argument("--seed", type=int, default=DEFAULT_SEED)
    parser.add_argument("--test-size", type=float, default=DEFAULT_TEST_SIZE)
    args = parser.parse_args()

    rows, data_quality = read_and_audit_dataset(args.csv)
    report = evaluate_dataset(rows, data_quality, args.seed, args.test_size)
    args.report.parent.mkdir(parents=True, exist_ok=True)
    with args.report.open("w", encoding="utf-8") as output_file:
        json.dump(report, output_file, indent=2)
        output_file.write("\n")
    print(f"Wrote workflow-failure evaluation report to {args.report}")


if __name__ == "__main__":
    main()
